const icon=name=>'<svg aria-hidden="true"><use href="#'+name+'"/></svg>';
const labels={dashboard:'Dashboard',config:'Configuração Bancária',validator:'Validador de Remessa',reports:'Relatórios',banks:'Bancos Disponíveis'};
